def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    change = new_value - old_value
    change_ratio_percent = (change / old_value) * 100

    return {
        "value": change_ratio_percent,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "change_ratio": change_ratio_percent,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
